import {faults,tests} from './model.mjs';
export const progressKey='mecanica.autos.guided.v1';
export function context(s){return {fault:s.fault,block:s.block,key:s.key,started:!!s.started,measured:[...s.measured]};}
export function validContext(c){return c&&faults[c.fault]&&['engine','electric','diagnosis'].includes(c.block)&&['off','crank','run'].includes(c.key)&&Array.isArray(c.measured)&&c.measured.every(k=>tests[k]);}
export function cleanRecords(data){return (Array.isArray(data)?data:[]).filter(r=>r&&typeof r.id==='string'&&typeof r.date==='string'&&Number.isFinite(r.score)&&Array.isArray(r.log)).slice(-100).map(r=>({...r,score:Math.max(0,Math.min(100,r.score)),hints:Number.isFinite(r.hints)?r.hints:0,log:r.log.filter(e=>e&&tests[e.choice]&&typeof e.correct==='boolean').slice(0,64),hintLog:(Array.isArray(r.hintLog)?r.hintLog:[]).filter(e=>validContext(e.before)).slice(0,16)}));}
export function recordGuide(s,g){return {id:s.id,date:g.date,status:g.phase==='complete'?'complete':'partial',score:Math.max(0,100-g.log.filter(e=>!e.correct).length*10-(g.hintLog?.length||0)*10),hints:g.hintLog?.length||0,reviewOf:g.reviewOf||null,reviewTest:g.reviewTest||null,log:structuredClone(g.log),hintLog:structuredClone(g.hintLog||[])};}
export function upsert(records,r){return [...records.filter(x=>x.id!==r.id),r].slice(-100);}
export function statistics(records){return Object.keys(tests).map(id=>{const events=records.flatMap(r=>r.log).filter(e=>e.choice===id),wrong=events.filter(e=>!e.correct).length;return {id,total:events.length,wrong,correct:events.length-wrong,rate:events.length?Math.round(100*wrong/events.length):null};}).sort((a,b)=>b.wrong-a.wrong||b.total-a.total);}
export function reviewTargets(records){const targets=[];for(const stat of statistics(records)){const cases=records.flatMap(r=>r.log.filter(e=>e.choice===stat.id&&!e.correct&&validContext(e.before)).map(e=>({record:r.id,choice:stat.id,before:e.before,reason:'Elegida cuando no era prioritaria',wrong:stat.wrong})));if(cases.length)targets.push(cases.at(-1));}if(!targets.length){for(const r of records.slice().reverse())for(const h of r.hintLog||[]){if(validContext(h.before)&&tests[h.recommended?.[0]])targets.push({record:r.id,choice:h.recommended[0],before:h.before,reason:'Necesitaste una pista',wrong:0});}}return targets.filter(t=>!records.some(r=>r.reviewOf===t.record&&r.reviewTest===t.choice&&r.status==='complete'&&r.hints===0&&r.log.length&&r.log.every(e=>e.correct))).slice(0,3);}
